import{_ as o,o as s,c as r,ah as a,j as e,a as t}from"./chunks/framework.C1NiJdpn.js";const c="/projects/JetRover/en/jetson-orin-nano/assets/image4.C6-fOXe5.png",l="/projects/JetRover/en/jetson-orin-nano/assets/image5.DwMp1iqc.jpeg",d="/projects/JetRover/en/jetson-orin-nano/assets/image6.BWBzoUnY.jpeg",p="/projects/JetRover/en/jetson-orin-nano/assets/image7.D4GczCrD.png",h="/projects/JetRover/en/jetson-orin-nano/assets/image8.DMY9IstT.png",g="/projects/JetRover/en/jetson-orin-nano/assets/image9.BiAGh7P1.png",m="/projects/JetRover/en/jetson-orin-nano/assets/image10.CD145lcj.png",u="/projects/JetRover/en/jetson-orin-nano/assets/image11.z6rIK6vO.png",A="/projects/JetRover/en/jetson-orin-nano/assets/image12.DmsMgyoc.png",v="data:image/png;base64,",b="/projects/JetRover/en/jetson-orin-nano/assets/image14.C0Km-nAr.png",f="/projects/JetRover/en/jetson-orin-nano/assets/image15.Z6rFE688.png",y="/projects/JetRover/en/jetson-orin-nano/assets/image16.vhdhRJgC.png",k="/projects/JetRover/en/jetson-orin-nano/assets/image17.BY5LYkqT.png",i="data:image/png;base64,",L=JSON.parse('{"title":"3. Lidar Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Lidar_Course.md","filePath":"docs/3.Lidar_Course.md"}'),w={name:"docs/3.Lidar_Course.md"};function C(S,n,T,z,I,E){return s(),r("div",null,[...n[0]||(n[0]=[a('<h1 id="_3-lidar-course" tabindex="-1">3. Lidar Course <a class="header-anchor" href="#_3-lidar-course" aria-label="Permalink to &quot;3. Lidar Course&quot;">​</a></h1><h2 id="_3-1-lidar-introduction" tabindex="-1">3.1 Lidar Introduction <a class="header-anchor" href="#_3-1-lidar-introduction" aria-label="Permalink to &quot;3.1 Lidar Introduction&quot;">​</a></h2><h3 id="_3-1-1-preface" tabindex="-1">3.1.1 Preface <a class="header-anchor" href="#_3-1-1-preface" aria-label="Permalink to &quot;3.1.1 Preface&quot;">​</a></h3><p>Lidar, a high-precision and high-speed remote sensing technology, is pivotal in numerous domains, including map creation, autonomous driving, environmental perception, and robot navigation. This document provides an overview of Lidar&#39;s principles, components, working mechanisms, application areas, advantages, and development trends.</p><p>In autonomous driving and intelligent transportation, Lidar assumes a critical role by offering real-time perception of obstacles, pedestrians, and vehicles on the road, providing precise distance and location information. In robot navigation and environmental perception, Lidar contributes by furnishing accurate maps and information about the surrounding environment. Furthermore, Lidar finds extensive applications in areas such as 3D modeling, map creation, safety monitoring, and remote sensing mapping.</p><img loading="lazy" height="330" width="611" src="'+c+'" class="common_img"><h3 id="_3-1-2-lidar-composition-and-classification" tabindex="-1">3.1.2 Lidar Composition and Classification <a class="header-anchor" href="#_3-1-2-lidar-composition-and-classification" aria-label="Permalink to &quot;3.1.2 Lidar Composition and Classification&quot;">​</a></h3><p>Lidar is composed of essential components such as a laser emitter, receiver, photodetector, scanning mechanism, and angle resolver. The laser emitter produces laser beams, while the receiver and photodetector capture reflected light signals. The scanning mechanism is responsible for surveying the surrounding environment, and the angle resolver assists in determining the position of target objects.</p><p>Lidar can be categorized into various types based on the scanning method:</p><ul><li><p><strong>Rotating Lidar</strong>: Achieves omnidirectional scanning horizontally by rotating the emitter or scanning mechanism. Known for high scanning speed and measurement accuracy, it is widely applied in areas such as autonomous driving, 3D environmental modeling, and map creation.</p></li><li><p><strong>Solid-State Lidar</strong>: Utilizes solid-state laser emitters, eliminating the need for rotating components. Compact, lightweight, and energy-efficient, solid-state lidar is suitable for applications like mobile devices, drones, and robots.</p></li><li><p><strong>Mechanical Lidar</strong>: Employs mechanical components like rotating mirrors or prisms for laser beam scanning. Although offering longer measurement distances and higher accuracy, mechanical lidar tends to have slower scanning speeds. It is commonly used in terrain measurement, building scanning, and navigation.</p></li><li><p><strong>Phase-Modulated Lidar</strong>: Measures the distance between target objects and the lidar by altering the phase of the laser beam. Known for high measurement accuracy and a large measurement range, phase-modulated lidar is extensively used in map creation, surveying, and industrial applications.</p></li><li><p><strong>Flash Lidar</strong>: Utilizes brief, high-power laser pulses to illuminate the entire scene simultaneously. It captures reflected light signals through an array of receivers, making it suitable for high-speed and high-resolution applications, including rapid scene capture and motion tracking.</p></li></ul><h3 id="_3-1-3-switch-lidar-version" tabindex="-1">3.1.3 Switch Lidar Version <a class="header-anchor" href="#_3-1-3-switch-lidar-version" aria-label="Permalink to &quot;3.1.3 Switch Lidar Version&quot;">​</a></h3><p>The robot provides two Lidar options, and the default Lidar version in the system image is <code>G4</code> Lidar. Therefore, please confirm the Lidar version upon you receiving the robot kit.</p><p>(1) If the Lidar you are using serves as <code>G4</code> Lidar, you don&#39;t need to change the Lidar configuration in the system image. If you are using <code>A1</code> Lidar, please follow the below steps to switch the Lidar version.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="602" width="606" src="'+l+'" style="width:330px;"><img loading="lazy" height="586" width="606" src="'+d+'" style="width:450px;"></p><p>(2) Start the robot, and connect it to <code>NoMachine</code> according to the instructions provided in <a href="./1.Quick_Start_Guide.html#development-environment-setup-and-configuration">1.6 Development Environment Setup and Configuration</a>.</p><img loading="lazy" height="671" width="1267" src="'+p+'" class="common_img">',16),e("p",null,[t("(3) After successful connection, double-click "),e("img",{loading:"lazy",height:"67",width:"48",src:h,JetRover:"",alt:"4.1"}),t(".")],-1),a('<img loading="lazy" height="377" width="752" src="'+g+'" class="common_img"><p>(4) Click the dropdown menu in the <code>Lidar</code> tab and choose the Lidar model that corresponds to your robot, such as <strong>&#39;G4.&#39;</strong> Then, click <strong>&#39;Save&#39;</strong> and <strong>&#39;Apply&#39;</strong> to confirm your choice.</p><img loading="lazy" height="377" width="752" src="'+m+'" class="common_img"><p>(5) A popup window will appear as shown in the image below, indicating that the robot&#39;s auto-start service will restart, and the laser radar model will be configured according to the selected option.</p><img loading="lazy" height="377" width="752" src="'+u+'" class="common_img"><p>(6) After the system completes a restart, click-on <strong>&quot;Quit&quot;</strong> icon.</p><img loading="lazy" height="377" width="752" src="'+A+'" class="common_img">',7),e("p",null,[t("(7) Finally, click-on "),e("img",{loading:"lazy",height:"44",width:"53",src:v,JetRover:""}),t(" to confirm the Lidar version.")],-1),a('<img loading="lazy" height="212" width="734" src="'+b+'" class="common_img"><h2 id="_3-2-lidar-working-and-ranging-principle" tabindex="-1">3.2 Lidar Working and Ranging Principle <a class="header-anchor" href="#_3-2-lidar-working-and-ranging-principle" aria-label="Permalink to &quot;3.2 Lidar Working and Ranging Principle&quot;">​</a></h2><h3 id="_3-2-1-lidar-ranging" tabindex="-1">3.2.1 Lidar Ranging <a class="header-anchor" href="#_3-2-1-lidar-ranging" aria-label="Permalink to &quot;3.2.1 Lidar Ranging&quot;">​</a></h3><p>Two common methods are employed by Lidar to determine the distance to a target: <code>triangulation</code> and <code>Time of Flight (TOF)</code>.</p><p>In the case of <code>TOF</code>, as depicted in the diagram, the Lidar initially projects light onto the object. The object reflects the light directly back to the Lidar, which calculates the time it takes for the light to return. The distance between the object and the Lidar is then obtained by multiplying this time by the speed of light.</p><img loading="lazy" height="311" width="820" src="'+f+'" class="common_img"><p>In <code>triangulation</code>, as illustrated in the diagram, the Lidar undergoes adjustments during manufacturing to ensure that the light does not directly strike the object. Instead, it is projected at a specific angle, a pre-set value that remains constant during operation. The distance from the object to the Lidar can be calculated by incorporating this angle into trigonometric functions.</p><img loading="lazy" height="313" width="809" src="'+y+'" class="common_img"><h3 id="_3-2-2-lidar-working-result" tabindex="-1">3.2.2 Lidar Working Result <a class="header-anchor" href="#_3-2-2-lidar-working-result" aria-label="Permalink to &quot;3.2.2 Lidar Working Result&quot;">​</a></h3><p>Its working result is as follows. Lidar will emit light and shine it on the object surface. When receiving the light reflected by the object, Lidar will mark the contour of the object at the position where the light is reflected.</p><img loading="lazy" height="556" width="770" src="'+k+'" class="common_img"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 Lidar Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 Lidar Obstacle Avoidance&quot;">​</a></h2><p>The robot senses the distance between itself and an object directly in front of it. Depending on the configured distance, the robot will either turn left or right to avoid obstacles. If no obstacles are detected, it will proceed to move forward.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.Quick_Start_Guide.html#app-control">1.5 APP Control</a>.</p><p>(1) Start the robot, and access the robot system desktop using <code>NoMachine</code> according to the tutorial saved in <a href="./1.Quick_Start_Guide.html#development-environment-setup-and-configuration">1.6 Development Environment Setup and Configuration</a>.</p>',16),e("p",null,[t("(2) Click-on "),e("img",{loading:"lazy",height:"38",width:"45",src:i,JetRover:""}),t(" to start the command line terminal.")],-1),a('<p>(3) Execute the command and press Enter key to deactivate the automatic start service for the app.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><p>(4) Enter the command and press Enter to start the robot&#39;s auto-start program:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><p>(5) Open a new command line terminal, type the command, and press Enter to access the Lidar feature</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><p>(6) Enter the command and hit Enter to launch Lidar obstacle avoidance game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 1}&quot;</span></span></code></pre></div><p>(7) If you need to stop the current function, simply enter the command in the current command line terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press <strong>&quot;Ctrl+C&quot;</strong> in the terminal interface at step (4) or (5).</p><h2 id="_3-4-lidar-following" tabindex="-1">3.4 Lidar Following <a class="header-anchor" href="#_3-4-lidar-following" aria-label="Permalink to &quot;3.4 Lidar Following&quot;">​</a></h2><p>The robot monitors the distance between itself and an object directly in front. If the distance exceeds 35cm, it will track the object ahead. If the distance is less than 35cm, it will reverse. The robot automatically halts when the distance directly in front is detected as 35cm.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.Quick_Start_Guide.html#app-control">1.5 APP Control</a>.</p><p>(1) Start the robot, and access the robot system desktop using <code>NoMachine</code> according to the tutorial saved in <a href="./1.Quick_Start_Guide.html#development-environment-setup-and-configuration">1.6 Development Environment Setup and Configuration</a>.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+i+'"> to start the command line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><p>(4) Run the command to enable the local services for app-related game and chassis control services.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><p>(5) Open a new ROS2 terminal, and execute the command, then press Enter to start the Lidar game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><p>(6) Enter the command and hit Enter to launch Lidar following game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 2}&quot;</span></span></code></pre></div><p>(7) If you need to stop the current function, simply enter the command in the current command line terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press <strong>&quot;Ctrl+C&quot;</strong> in the terminal interface at step (4) or (5).</p><h2 id="_3-5-lidar-guarding" tabindex="-1">3.5 Lidar Guarding <a class="header-anchor" href="#_3-5-lidar-guarding" aria-label="Permalink to &quot;3.5 Lidar Guarding&quot;">​</a></h2><p>The JetRover in the Ackerman configuration currently does not support the radar security feature.</p><p>The robot can detect the distance to objects directly in front of it; if an object is within a specified distance, the robot will turn to face it.</p><p>There are two ways to enable this feature: first, through the mobile app, and second, by connecting remotely and using commands.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.Quick_Start_Guide.html#app-control">1.5 APP Control</a>.</p><p>(1) Start the robot, and access the robot system desktop using <code>NoMachine</code> according to the tutorial saved in <a href="./1.Quick_Start_Guide.html#development-environment-setup-and-configuration">1.6 Development Environment Setup and Configuration</a>.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+i+'"> to start the command line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><p>(4) Run the command to enable the local services for app-related game and chassis control services.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><p>(5) Open a new ROS2 terminal, and execute the command, then press Enter key to start the Lidar game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><p>(6) Create a new command-line terminal and hit Enter key to launch Lidar guarding game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 3}&quot;</span></span></code></pre></div><p>(7) If you need to stop the current function, simply enter the command in the current command line terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_controller/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press <strong>&quot;Ctrl+C&quot;</strong> in the terminal interface at step (4) or (5).</p>',46)])])}const R=o(w,[["render",C]]);export{L as __pageData,R as default};
